    return Array.isArray(data.errors)
      ? `${data.message}: ${data.errors.map((v) => JSON.stringify(v)).join(", ")}${suffix}`
      : `${data.message}${suffix}`;
  }

  return `Unknown error: ${JSON.stringify(data)}`;
}

import { endpoint } from "@octokit/endpoint";
import defaults from "./defaults.js";
import withDefaults from "./with-defaults.js";

export const request = withDefaults(endpoint, defaults);

export function isPlainObject(value: unknown): value is Object {
  if (typeof value !== "object" || value === null) return false;

  if (Object.prototype.toString.call(value) !== "[object Object]") return false;

  const proto = Object.getPrototypeOf(value);
  if (proto === null) return true;

  const Ctor =
    Object.prototype.hasOwnProperty.call(proto, "constructor") &&
    proto.constructor;
  return (
    typeof Ctor === "function" &&
    Ctor instanceof Ctor &&
    Function.prototype.call(Ctor) === Function.prototype.call(value)
  );
}

import fetchWrapper from "./fetch-wrapper.js";
import type {
  EndpointOptions,
  EndpointInterface,
  OctokitResponse,
  Route,
  RequestInterface,
  RequestParameters,
} from "@octokit/types";

export default function withDefaults(
  oldEndpoint: EndpointInterface,
  newDefaults: RequestParameters,
): RequestInterface {
  const endpoint = oldEndpoint.defaults(newDefaults);
  const newApi = function (
    route: Route | EndpointOptions,
    parameters?: RequestParameters,
  ): Promise<OctokitResponse<any>> {
    const endpointOptions = endpoint.merge(<Route>route, parameters);

    if (!endpointOptions.request || !endpointOptions.request.hook) {
      return fetchWrapper(endpoint.parse(endpointOptions));
    }

    const request = (
      route: Route | EndpointOptions,
      parameters?: RequestParameters,
    ) => {
      return fetchWrapper(
        endpoint.parse(endpoint.merge(<Route>route, parameters)),
      );
    };

    Object.assign(request, {
      endpoint,
      defaults: withDefaults.bind(null, endpoint),
    });

    return endpointOptions.request.hook(request, endpointOptions);
  };

  return Object.assign(newApi, {
    endpoint,
    defaults: withDefaults.bind(null, endpoint),
  }) as RequestInterface<typeof endpoint.DEFAULTS & typeof newDefaults>;
}

